const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-70.647985, -34.752733]).buffer(10000); // 10km buffer for basin area
  const collectionId = 'MODIS/061/MOD10A1';
  const snowBand = 'NDSI_Snow_Cover';
  const snowThreshold = 15; // Pixels with >15% snow cover are considered "snow"

  // 2. Data Acquisition & Processing for Target Year (2023)
  const targetDate = ee.Date('2023-12-18');
  const targetCollection = ee.ImageCollection(collectionId)
    .filterDate(targetDate, targetDate.advance(1, 'day'))
    .filterBounds(aoi);

  const targetCollectionSize = targetCollection.size().getInfo();
  if (targetCollectionSize === 0) {
    console.log('No image found for 2023-12-18.');
    console.log('A');
    return;
  }

  const image2023 = ee.Image(targetCollection.first());
  // Create a binary mask where snow is 1, no-snow is 0, and other values (clouds etc.) are masked
  const snowMask2023 = image2023.select(snowBand)
    .gte(snowThreshold) // get pixels with snow cover >= threshold
    .updateMask(image2023.select(snowBand).lte(100)); // mask out clouds/errors (values > 100)

  // Calculate the area of snow in square kilometers
  const snowArea2023 = snowMask2023.multiply(ee.Image.pixelArea())
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 500, // MODIS resolution
      maxPixels: 1e9
    }).get(snowBand);

  // 3. Data Acquisition & Processing for Historical Years (2017-2022)
  const historicalYears = ee.List.sequence(2017, 2022);

  const historicalSnowAreas = historicalYears.map(function(year) {
    const date = ee.Date.fromYMD(year, 12, 18);
    const image = ee.ImageCollection(collectionId)
      .filterDate(date, date.advance(1, 'day'))
      .filterBounds(aoi)
      .first();

    // Return a feature with null area if no image exists for that day
    return ee.Feature(null, ee.Algorithms.If(
        image,
        image.select(snowBand)
            .gte(snowThreshold)
            .updateMask(image.select(snowBand).lte(100))
            .multiply(ee.Image.pixelArea())
            .reduceRegion({
                reducer: ee.Reducer.sum(),
                geometry: aoi,
                scale: 500,
                maxPixels: 1e9
            }),
        {'NDSI_Snow_Cover': null} // Handle case where no image exists
    ));
  });

  // Calculate the average historical snow area, ignoring nulls
  const historicalAvgArea = ee.FeatureCollection(historicalSnowAreas)
    .aggregate_mean(snowBand);

  // 4. Validation & Final Answer
  const finalValues = ee.Dictionary({
      'snow_2023': snowArea2023,
      'historical_avg': historicalAvgArea
  }).getInfo();

  const snow2023 = finalValues['snow_2023'];
  const histAvg = finalValues['historical_avg'];

  if (snow2023 === null || histAvg === null) {
      console.log(`2023 Snow Area (sq km): ${snow2023 === null ? 'No Valid Pixels' : (snow2023 / 1e6).toFixed(2)}`);
      console.log(`Historical Average (sq km): ${histAvg === null ? 'No Valid Pixels' : (histAvg / 1e6).toFixed(2)}`);
      if (snow2023 === 0) {
        console.log('No valid pixels found for 2023 image after masking.');
        console.log('C2');
      } else if (histAvg === 0) {
        console.log('No valid pixels found for historical images after masking.');
        console.log('C2');
      } else {
        console.log('Could not calculate one or both values.');
        console.log('C3');
      }
      return;
  }

  const snow2023_km2 = snow2023 / 1e6;
  const histAvg_km2 = histAvg / 1e6;

  console.log(`Snow Cover Area on 2023-12-18 (sq km): ${snow2023_km2.toFixed(2)}`);
  console.log(`Average Snow Cover on Dec 18 (2017-2022) (sq km): ${histAvg_km2.toFixed(2)}`);

  if (snow2023_km2 > histAvg_km2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
